"""Buildless, local-only pilot replay interface; no external resources."""

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AH · Model replay</title><style>
:root{color-scheme:light;--ink:#192c35;--muted:#62717a;--line:#dce2e5;--blue:#286b8b;--amber:#a35b0a;--paper:#f4f6f7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}header{height:72px;padding:0 28px;background:white;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:16px}.mark{border:1px solid #294b5b;padding:5px 9px;font-size:17px;font-weight:750;letter-spacing:1px}h1{font-size:19px;margin:0;font-weight:650}p{margin:0}.muted{color:var(--muted)}.small{font-size:12px}.tag{font-size:11px;letter-spacing:.6px;text-transform:uppercase;background:#edf3f5;padding:5px 9px;border-radius:3px}.shell{display:grid;grid-template-columns:225px minmax(0,1fr);min-height:calc(100vh - 72px)}aside{background:#fff;border-right:1px solid var(--line);padding:22px 13px}.sectionlabel{font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:1px;padding:0 10px;margin-bottom:10px}.clip{display:block;width:100%;text-align:left;border:1px solid transparent;background:none;padding:10px;border-radius:4px;color:var(--ink);cursor:pointer;margin-bottom:4px}.clip:hover{background:#f2f5f6}.clip.selected{background:#e9f1f5;border-color:#bacdd7}.clip strong{display:block;font-size:13px}.clip span{display:block;font-size:11px;color:var(--muted)}main{padding:22px 26px;max-width:1650px;width:100%}.notice{border-left:3px solid #b99345;padding:9px 12px;background:#faf7ef;color:#675524;font-size:12px;margin-bottom:20px}.toolbar{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:14px}h2{font-size:21px;margin:0 0 3px;font-weight:650}.selects{display:flex;gap:10px}label{font-size:11px;color:var(--muted);display:block}select{display:block;padding:7px 28px 7px 9px;border:1px solid #bdc9ce;background:white;color:var(--ink);border-radius:3px;font:13px system-ui;margin-top:3px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 255px;gap:16px}.panel{background:white;border:1px solid var(--line);border-radius:5px;overflow:hidden}.video-wrap{position:relative;background:#101820;aspect-ratio:16/9;display:flex;align-items:center;justify-content:center}video{width:100%;height:100%;display:block}#pose{position:absolute;left:0;top:0;width:100%;height:100%;pointer-events:none}.stamp{position:absolute;top:12px;left:12px;color:#fff;background:#10222bcc;padding:4px 8px;font:12px ui-monospace,Consolas,monospace;pointer-events:none}.video-note{padding:9px 13px;display:flex;gap:12px;align-items:center;justify-content:space-between;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.check{display:flex;align-items:center;gap:4px;white-space:nowrap}.side-panel{padding:17px}.metric{border-bottom:1px solid var(--line);padding:0 0 15px;margin-bottom:15px}.metric:last-child{border:0;padding:0;margin:0}.metric label{margin-bottom:5px}.value{font-size:22px;font-weight:650;line-height:1.3}.state{font-size:14px;font-weight:650;display:inline-block;padding:5px 9px;background:#edf3f5;border-radius:3px}.state.warning{background:#fff0da;color:#88500b}.state.unavailable{background:#eceff0;color:#5f6971}.state.building{background:#fff7e6;color:#865d23}.scorebar{height:5px;background:#e4ecef;margin:10px 0 5px}.scorebar i{display:block;height:100%;width:0;background:var(--blue)}.timeline{margin-top:16px;padding:14px 16px}.panel-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-weight:600}.legend{font-size:11px;font-weight:400;color:var(--muted);display:flex;gap:13px;flex-wrap:wrap}.legend span:before{content:'';display:inline-block;width:9px;height:3px;background:var(--blue);margin-right:5px;vertical-align:middle}.legend .warn:before{background:#cf7b20}.legend .exit:before{background:#4e8d75}.legend .missing:before{background:#a8b1b6}#timeline{display:block;width:100%;height:175px;cursor:crosshair}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.detail{padding:15px 17px}.detail h3{font-size:13px;margin:0 0 10px}.event{display:flex;width:100%;justify-content:space-between;gap:10px;padding:9px 0;border:0;border-top:1px solid #edf0f2;background:none;text-align:left;color:var(--ink);cursor:pointer;font:12px system-ui}.event:hover{color:var(--blue)}.empty{font-size:12px;color:var(--muted);padding:5px 0}.foot{margin-top:15px;font-size:11px;color:var(--muted)}#error{color:#983d2f;background:#fff0ed;padding:10px;display:none}#preparing{color:#c4d0d6;text-align:center;padding:30px}.action{border:1px solid #b9c9d0;border-radius:3px;padding:5px 9px;background:white;color:var(--ink);cursor:pointer;font:12px system-ui}.action:hover{background:#eef4f6}:focus-visible{outline:2px solid #286b8b;outline-offset:3px}@media(max-width:1150px){main{padding:18px}.shell{grid-template-columns:190px minmax(0,1fr)}.workspace{grid-template-columns:minmax(0,1fr)}.side-panel{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.metric{border:0;margin:0;padding:0}.toolbar{align-items:start;flex-direction:column}}@media(max-width:700px){header{padding:12px 16px;height:auto}.shell{display:block}aside{border-right:0;border-bottom:1px solid var(--line);padding:10px}.sectionlabel{display:none}#clips{display:flex;overflow:auto}.clip{min-width:165px;margin:0 4px 0 0}main{padding:14px}.bottom{grid-template-columns:1fr}.value{font-size:18px}.legend{gap:7px}.tag{display:none}}
</style><style>[hidden]{display:none!important}</style></head><body>
<header><div class="brand"><span class="mark">AH</span><div><h1>Model replay</h1><p class="muted small">Recorded session · 13 October 2026</p></div></div><span class="tag">Local only · No live alerts</span></header>
<div class="shell"><aside><div class="sectionlabel">12 recorded trials</div><nav id="clips" aria-label="Recordings"></nav></aside><main>
<div class="notice"><strong>Training-data replay.</strong> These recordings were used to fit the models. Scores and warnings here demonstrate behaviour, not performance on new people.</div>
<div id="error" role="alert"></div><div class="toolbar"><div><h2 id="title">Loading recordings…</h2><p id="subtitle" class="muted small">Fixed view · Nearest and middle beds</p></div><div class="selects"><label>Model<select id="model"><option value="rgb_depth_logistic">Pose + depth · logistic</option><option value="rgb_logistic">Pose only · logistic</option><option value="rgb_depth_tree">Pose + depth · tree</option><option value="rgb_tree">Pose only · tree</option></select></label><label>Exit horizon<select id="horizon"><option value="5">5 seconds</option><option value="10" selected>10 seconds</option><option value="20">20 seconds</option></select></label></div></div>
<div class="workspace"><section class="panel"><div class="video-wrap"><video id="video" controls preload="metadata" playsinline aria-label="Recorded trial video"></video><canvas id="pose"></canvas><div id="preparing" hidden>Preparing a local video copy…<br><small>This page will update when it is ready.</small></div><div class="stamp" id="stamp">Original time 0.00 s</div></div><div class="video-note"><span>Original timestamps · 10 Hz preview</span><label class="check"><input id="skeleton" type="checkbox"> Show pose</label><button id="firstWarning" class="action">First warning</button></div></section>
<section class="panel side-panel"><div class="metric"><label>SIMULATED WARNING</label><div id="state" class="state unavailable">Waiting for video</div><p id="reason" class="muted small" style="margin-top:7px">No alerts leave this page.</p></div><div class="metric"><label>MODEL PHASE</label><div id="phase" class="value">—</div><p class="muted small" id="reviewPhase">Existing review: —</p></div><div class="metric"><label id="scoreLabel">EXIT SCORE · NEXT 10 S</label><div class="value" id="score">—</div><div class="scorebar"><i id="scoreFill"></i></div><p class="muted small">Uncalibrated model score, not a clinical probability.</p></div></section></div>
<section class="panel timeline"><div class="panel-title"><span>Warning timeline</span><div class="legend"><span>Model score</span><span class="warn">Warning</span><span class="exit">Reviewed exit interval</span><span class="missing">Unavailable</span></div></div><canvas id="timeline" aria-label="Click the timeline to seek the recording"></canvas><p id="policy" class="muted small">Demo policy · Score ≥ 0.70 for 0.5 s · Release ≤ 0.35 for 0.5 s · 3 s cooldown</p></section>
<div class="bottom"><section class="panel detail"><h3 id="eventTitle">Warning episodes</h3><div id="events"></div></section><section class="panel detail"><h3>Recording check</h3><div id="coverage" class="small"></div><div id="comparison" class="small" style="margin-top:10px"></div><p id="referenceNote" class="muted small" style="margin-top:10px"></p></section></div>
<p class="foot">Reference labels are approximate visual review. Bed identity is supplied by the recording, not validated tracking. Metric floor calibration is unverified; this replay uses no floor-height features. Camera capture, paging and live detection are unchanged.</p>
</main></div><script>
'use strict';
const $=id=>document.getElementById(id),video=$('video');let catalog=[],data=null,currentClip=5,generation=0,mediaClip=null,currentT=0;
const words=s=>(s||'').replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
function error(message){$('error').textContent=message;$('error').style.display=message?'block':'none'}
async function get(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error('Cannot load replay ('+r.status+').');return r.json()}
function lastAt(values,t,key=x=>x){let lo=0,hi=values.length-1,best=-1;while(lo<=hi){let m=(lo+hi)>>1;if(key(values[m])<=t+0.00011){best=m;lo=m+1}else hi=m-1}return best}
function clipButtons(){const list=$('clips');list.replaceChildren();for(const c of catalog){const b=document.createElement('button');b.className='clip'+(c.id===currentClip?' selected':'');const strong=document.createElement('strong'),sub=document.createElement('span');strong.textContent=String(c.id).padStart(2,'0')+' · '+words(c.name.replace(c.bed+' ',''));sub.textContent=words(c.bed)+' bed · '+(c.video_ready?c.duration_s.toFixed(0)+' s':'Preparing video');b.append(strong,sub);b.onclick=()=>load(c.id);list.append(b)}}
function seekSource(t){if(!data?.media)return;const i=Math.max(0,lastAt(data.media.frame_times_s,t));video.currentTime=(i+.05)/data.media.fps}
async function load(clip){const request=++generation;video.pause();error('');currentClip=clip;clipButtons();try{const r=await get('/api/replay?clip='+clip+'&model='+$('model').value+'&horizon='+$('horizon').value);if(request!==generation)return;data=r;const c=catalog.find(c=>c.id===clip);$('title').textContent=words(c.name.replace(c.bed+' ',''));$('subtitle').textContent='Clip '+String(clip).padStart(2,'0')+' · '+words(c.bed)+' bed · '+r.duration_s.toFixed(1)+' s';$('scoreLabel').textContent='EXIT SCORE · NEXT '+r.horizon_s+' S';$('preparing').hidden=!!r.media;video.hidden=!r.media;$('pose').hidden=!r.media;$('stamp').hidden=!r.media;if(r.media&&mediaClip!==clip){video.src='/video?clip='+clip;mediaClip=clip;video.load();currentT=0}else if(!r.media){video.removeAttribute('src');video.load();mediaClip=null;currentT=0}details();update();}catch(e){error(e.message)}}
function details(){
 const r=data;$('eventTitle').textContent='Warning episodes · '+r.events.length;$('events').replaceChildren();
 for(const e of r.events){const b=document.createElement('button');b.className='event';const l=document.createElement('span'),v=document.createElement('span');l.textContent=e.t.toFixed(2)+' s · '+words(e.phase);v.textContent='Score '+e.score.toFixed(2)+'  ↗';b.append(l,v);b.onclick=()=>seekSource(Math.max(0,e.t-2));$('events').append(b)}
 if(!r.events.length){const p=document.createElement('p');p.className='empty';p.textContent='No warnings under this demo policy.';$('events').append(p)}
 $('firstWarning').disabled=!r.events.length;$('firstWarning').onclick=()=>seekSource(Math.max(0,r.events[0].t-2));
 $('coverage').textContent=r.available_s.toFixed(1)+' s observable · '+r.unavailable_s.toFixed(1)+' s unavailable / '+r.duration_s.toFixed(1)+' s';
 const lines=r.comparison.matches.map(m=>{
   const reference='Reviewed exit '+m.exit_interval_s.map(t=>t.toFixed(2)).join('–')+' s. ';
   if(m.earlier_warning_s!==undefined)return reference+'Warning began at '+m.earlier_warning_s.toFixed(2)+' s ('+m.earlier_lead_time_bounds_s.map(t=>t.toFixed(1)).join('–')+' s before exit), earlier than the selected '+r.horizon_s+' s comparison window.';
   return reference+(m.warning_s===undefined?'No warning in the comparison window.':words(m.classification)+': warning '+m.warning_s.toFixed(2)+' s; lead '+m.lead_time_bounds_s.map(t=>t.toFixed(1)).join('–')+' s.');
 });
 if(!r.reference_exits.length)lines.push('No exit in the existing reviewed reference.');
 if(r.comparison.unmatched_warnings.length&&!r.comparison.matches.some(m=>m.earlier_warning_s!==undefined))lines.push(r.comparison.unmatched_warnings.length+' warning(s) without a one-to-one reference match.');
 $('comparison').textContent=lines.join(' ');$('referenceNote').textContent=r.reference_notes
}
function sourceTime(){if(!data?.media)return 0;const m=data.media;const i=Math.min(m.frames-1,Math.max(0,Math.floor(video.currentTime*m.fps+1e-4)));return m.frame_times_s[i]||0}
function update(){if(!data)return;currentT=sourceTime();$('stamp').textContent='Original time '+currentT.toFixed(2)+' s';const i=lastAt(data.rows,currentT,r=>r.t),row=i>=0?data.rows[i]:null;const usable=data.media&&row&&currentT-row.t<=data.policy.max_gap_s&&row.available;let status=usable?row.status:'UNAVAILABLE';$('state').className='state '+(status==='WARNING'?'warning':status==='BUILDING'?'building':status==='UNAVAILABLE'?'unavailable':'');$('state').textContent={WARNING:'Warning would fire',BUILDING:'Building evidence',NO_WARNING:'No warning',UNAVAILABLE:'Monitoring unavailable'}[status];$('reason').textContent=usable?'Simulation only · No live alerts':words(row?.reason||'No usable observation');$('phase').textContent=usable?words(row.phase):'—';$('score').textContent=usable?row.score.toFixed(2):'—';$('scoreFill').style.width=usable?(row.score*100)+'%':'0%';const ref=data.reference_segments.find(s=>s[0]<=currentT&&currentT<s[1]);$('reviewPhase').textContent='Existing review: '+(ref?words(ref[2]):'Transition / unlabelled');drawTimeline();drawPose(usable?row:null)}
function context(canvas){const rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;const w=Math.max(1,rect.width),h=Math.max(1,rect.height);if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio)}const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);return[ctx,w,h]}
function drawTimeline(){const [g,w,h]=context($('timeline'));if(!data)return;const left=34,right=w-12,top=10,bottom=h-27,x=t=>left+(right-left)*t/data.duration_s,y=s=>bottom-(bottom-top)*s;g.font='10px system-ui';g.fillStyle='#73818a';for(const s of [0,.35,.7,1]){g.strokeStyle=s===.7?'#b8cbd3':'#e8edef';g.setLineDash(s===.7?[4,4]:[]);g.beginPath();g.moveTo(left,y(s));g.lineTo(right,y(s));g.stroke();g.fillText(s.toFixed(2),0,y(s)+3)}g.setLineDash([]);for(let t=0;t<=data.duration_s;t+=10)g.fillText(t+'s',x(t)-5,h-5);for(const [lo,hi]of data.reference_exits){g.fillStyle='#4e8d7530';g.fillRect(x(lo),top,x(hi)-x(lo),bottom-top)}for(let i=0;i<data.rows.length;i++){const r=data.rows[i],end=i+1<data.rows.length?data.rows[i+1].t:data.duration_s;if(!r.available){g.fillStyle='#b3bcc277';g.fillRect(x(r.t),bottom-4,Math.max(1,x(end)-x(r.t)),4)}}g.strokeStyle='#286b8b';g.lineWidth=1.7;g.beginPath();let pen=false,last=null;for(const r of data.rows){if(!r.available){pen=false;continue}if(!pen||last!==null&&r.t-last>data.policy.max_gap_s)g.moveTo(x(r.t),y(r.score));else g.lineTo(x(r.t),y(r.score));pen=true;last=r.t}g.stroke();for(const e of data.events){g.strokeStyle='#cf7b20';g.lineWidth=1.5;g.beginPath();g.moveTo(x(e.t),top);g.lineTo(x(e.t),bottom);g.stroke();g.fillStyle='#cf7b20';g.beginPath();g.moveTo(x(e.t)-4,top);g.lineTo(x(e.t)+4,top);g.lineTo(x(e.t),top+6);g.fill()}g.strokeStyle='#22343c';g.lineWidth=1;g.beginPath();g.moveTo(x(currentT),top);g.lineTo(x(currentT),bottom);g.stroke()}
const edges=[[5,6],[5,7],[7,9],[6,8],[8,10],[5,11],[6,12],[11,12],[11,13],[13,15],[12,14],[14,16]];
function drawPose(row){const [g,w,h]=context($('pose'));if(!$('skeleton').checked||!row?.keypoints)return;const pts=row.keypoints.map(p=>[p[0]/data.width*w,p[1]/data.height*h]);g.lineWidth=2;g.strokeStyle='#80e9d2';for(const [a,b]of edges)if(row.scores[a]>=.45&&row.scores[b]>=.45){g.beginPath();g.moveTo(...pts[a]);g.lineTo(...pts[b]);g.stroke()}g.fillStyle='#e4fff8';pts.forEach((p,i)=>{if(row.scores[i]>=.45){g.beginPath();g.arc(p[0],p[1],2.5,0,Math.PI*2);g.fill()}})}
$('timeline').onclick=e=>{if(!data)return;const r=e.currentTarget.getBoundingClientRect();seekSource(Math.max(0,Math.min(data.duration_s,(e.clientX-r.left-34)/(r.width-46)*data.duration_s)))};
video.addEventListener('timeupdate',update);video.addEventListener('seeked',update);video.addEventListener('loadedmetadata',()=>seekSource(data?.events.length?Math.max(1,data.events[0].t-2):2));video.addEventListener('loadeddata',update);video.addEventListener('error',()=>{if(video.getAttribute('src'))error('Video could not be decoded. The prediction timeline is still available.');});$('skeleton').onchange=update;$('model').onchange=()=>load(currentClip);$('horizon').onchange=()=>load(currentClip);window.addEventListener('resize',update);
async function refresh(){try{const wasReady=catalog.find(c=>c.id===currentClip)?.video_ready;catalog=(await get('/api/clips')).clips;clipButtons();if(!data||(!wasReady&&catalog.find(c=>c.id===currentClip)?.video_ready))await load(currentClip)}catch(e){error(e.message)}}
refresh();setInterval(refresh,15000);
</script></body></html>'''
